files={'benchmark.py': '"""Measure the original VRPOTrainer through its existing runtime_factory hook."""\nimport json\nimport math\nimport os\nimport sys\nimport time\nfrom dataclasses import asdict\nfrom pathlib import Path\n\nimport torch\nfrom torch._dynamo.utils import counters\nfrom marvel.config import TrainConfig\nfrom marvel.training.workflow import TrainingWorkflow\nfrom marvel.training.vrpo import VRPOTrainer\nfrom marvel.utils import configure_torch\n\n\ndef main():\n    settings = json.loads(Path(sys.argv[1]).read_text())\n    out = Path(settings[\'output\'])\n    out.mkdir(parents=True, exist_ok=True)\n    torch.set_num_threads(settings[\'threads\'])\n    torch.set_num_interop_threads(1)\n    cfg = TrainConfig(algo_name=\'vrpo\', device=\'cuda\',\n        rollout_batch_size=settings[\'rollout\'], collect_batch_size=settings[\'collect\'],\n        mini_batches=settings[\'mini_batches\'], replay_buffer_scale=16,\n        total_iterations=settings[\'warmup\'] + settings[\'measure\'],\n        checkpoint_interval=-1, evaluation_interval=-1, param_stats_interval=-1,\n        seed=settings.get(\'seed\', 0), logging_dir=str(out / \'training\'))\n    configure_torch(cfg)\n    (out / \'train-config.json\').write_text(json.dumps(asdict(cfg), indent=2))\n    blocks = []\n    runtime_info = {}\n    class MeasuredWorkflow(TrainingWorkflow):\n        def __init__(self, cfg, **kwargs):\n            super().__init__(cfg, **kwargs)\n            runtime_info.update(effective_torch_threads=torch.get_num_threads(), effective_omp=os.environ.get(\'OMP_NUM_THREADS\'))\n            print(\'EFFECTIVE_THREADS \' + json.dumps(runtime_info), flush=True)\n        def checkpoint_due(self):\n            return False\n\n        def iterations(self):\n            block_size = settings.get(\'block_size\', settings[\'measure\'])\n            for iteration in super().iterations():\n                measured = iteration > settings[\'warmup\']\n                if measured and (iteration - settings[\'warmup\'] - 1) % block_size == 0:\n                    torch.cuda.synchronize()\n                    before = (self.env_steps_total, self.game_steps_total)\n                    graphs = counters[\'stats\'][\'unique_graphs\']\n                    start = time.perf_counter()\n                yield iteration\n                if measured and ((iteration - settings[\'warmup\']) % block_size == 0 or iteration == cfg.total_iterations):\n                    torch.cuda.synchronize()\n                    seconds = time.perf_counter() - start\n                    count = min(block_size, iteration - settings[\'warmup\'])\n                    row = dict(iteration=iteration, seconds=seconds,\n                        trajectories=count * cfg.collect_batch_size,\n                        env_steps=self.env_steps_total - before[0],\n                        game_steps=self.game_steps_total - before[1],\n                        new_graphs=counters[\'stats\'][\'unique_graphs\'] - graphs)\n                    blocks.append(row)\n                    print(\'BLOCK \' + json.dumps(row), flush=True)\n                if iteration in (1, settings[\'warmup\'], cfg.total_iterations):\n                    print(\'PROGRESS \' + str(iteration), flush=True)\n\n        def log_metrics(self):\n            assert all(math.isfinite(v) for v in self._metric_buffer.values() if isinstance(v, (int, float))), self._metric_buffer\n            super().log_metrics()\n\n    started = time.perf_counter()\n    VRPOTrainer(cfg, runtime_factory=lambda c: MeasuredWorkflow(c, game=c.game)).run()\n    seconds = sum(b[\'seconds\'] for b in blocks)\n    result = dict(settings=settings, blocks=blocks, seconds=seconds,\n        trajectories_per_second=sum(b[\'trajectories\'] for b in blocks) / seconds,\n        env_steps_per_second=sum(b[\'env_steps\'] for b in blocks) / seconds,\n        game_steps_per_second=sum(b[\'game_steps\'] for b in blocks) / seconds,\n        peak_allocated_mib=torch.cuda.max_memory_allocated() / 2**20,\n        peak_reserved_mib=torch.cuda.max_memory_reserved() / 2**20,\n        new_graphs=sum(b[\'new_graphs\'] for b in blocks),\n        wall_seconds=time.perf_counter() - started,\n        torch_version=torch.__version__, cuda_version=torch.version.cuda)\n    result.update(runtime_info)\n    assert not list(out.rglob(\'*.pt\')), \'Tuning must not save checkpoints\'\n    (out / \'measurement.json\').write_text(json.dumps(result, indent=2))\n    print(\'MEASUREMENT \' + json.dumps(result), flush=True)\n\nif __name__ == \'__main__\':\n    main()\n', 'run_search.py': '"""Bounded serial search on one G4. Each trial is a fresh process."""\nimport csv\nimport json\nimport os\nfrom pathlib import Path\nimport signal\nimport subprocess\nimport sys\nimport time\nimport traceback\n\nROOT = Path(\'/content/g4-vrpo\')\nOUT = ROOT / \'results\'\nREPO = ROOT / \'repo\'\nPROTOCOL = json.loads((ROOT / \'protocol.json\').read_text())\nOUT.mkdir(parents=True, exist_ok=True)\nSTART = time.monotonic()\nDEADLINE = START + 55 * 60\nENV = dict(os.environ, WANDB_DISABLED=\'true\', PYTHONUNBUFFERED=\'1\',\n    PYTORCH_ALLOC_CONF=\'expandable_segments:True\',\n    TORCHINDUCTOR_CACHE_DIR=str(ROOT / \'inductor-cache\'),\n    TORCHINDUCTOR_COMPILE_THREADS=\'2\', NANOPOKERLIB_BUILD_JOBS=\'4\')\nresults = []\n\n\ndef run(command, **kw):\n    subprocess.run(command, check=True, env=ENV, timeout=min(600, max(1, DEADLINE-time.monotonic())), **kw)\n\n\ndef trial(config, label, warmup=16, measure=8, seed=0):\n    if time.monotonic() > DEADLINE - 180:\n        raise TimeoutError(\'Search budget exhausted\')\n    folder = OUT / label\n    folder.mkdir()\n    settings = dict(config, warmup=warmup, measure=measure, block_size=8, seed=seed, output=str(folder))\n    (folder / \'settings.json\').write_text(json.dumps(settings))\n    env = dict(ENV, OMP_NUM_THREADS=str(config[\'threads\']), MKL_NUM_THREADS=str(config[\'threads\']), PYTHONPATH=str(REPO))\n    print(\'START \' + label + \' \' + json.dumps(settings), flush=True)\n    started = time.monotonic()\n    with (folder / \'gpu.csv\').open(\'w\') as gpu, (folder / \'train.log\').open(\'w\') as log:\n        monitor = subprocess.Popen([\'nvidia-smi\', \'--query-gpu=memory.used,memory.total,utilization.gpu\',\n            \'--format=csv,noheader,nounits\', \'--loop-ms=200\'], stdout=gpu, stderr=subprocess.DEVNULL)\n        process = subprocess.Popen([sys.executable, str(ROOT / \'benchmark.py\'), str(folder / \'settings.json\')],\n            cwd=REPO, env=env, stdout=log, stderr=subprocess.STDOUT, start_new_session=True)\n        timed_out = False\n        try:\n            process.wait(timeout=min(600, DEADLINE-time.monotonic()))\n        except subprocess.TimeoutExpired:\n            timed_out = True\n            os.killpg(process.pid, signal.SIGTERM)\n            try:\n                process.wait(timeout=10)\n            except subprocess.TimeoutExpired:\n                os.killpg(process.pid, signal.SIGKILL)\n                process.wait()\n        finally:\n            monitor.terminate()\n            monitor.wait(timeout=10)\n    samples = list(csv.reader((folder / \'gpu.csv\').read_text().splitlines()))\n    peak = max(float(r[0]) for r in samples if len(r) == 3)\n    total = float(samples[-1][1])\n    result = dict(label=label, config=config, seed=seed, exit_code=process.returncode,\n        timed_out=timed_out, gpu_peak_mib=peak, gpu_total_mib=total, wall_seconds=time.monotonic()-started)\n    measurement = folder / \'measurement.json\'\n    if measurement.exists() and process.returncode == 0:\n        result.update(json.loads(measurement.read_text()))\n        result[\'conservative_peak_mib\'] = max(peak, result[\'peak_reserved_mib\'] + 512)\n        result[\'headroom_mib\'] = total - result[\'conservative_peak_mib\']\n        result[\'eligible\'] = result[\'headroom_mib\'] >= max(3072, total * .15) and result[\'new_graphs\'] == 0\n    else:\n        result[\'eligible\'] = False\n        result[\'error_tail\'] = (folder / \'train.log\').read_text()[-6000:]\n    assert not list(folder.rglob(\'*.pt\'))\n    results.append(result)\n    (folder / \'result.json\').write_text(json.dumps(result, indent=2))\n    (OUT / \'results.json\').write_text(json.dumps(results, indent=2))\n    print(\'RESULT \' + json.dumps({k:v for k,v in result.items() if k not in (\'blocks\', \'error_tail\', \'settings\')}), flush=True)\n    if not measurement.exists():\n        print(result.get(\'error_tail\', \'\'), flush=True)\n    if result[\'exit_code\'] != 0 and \'out of memory\' not in result.get(\'error_tail\', \'\').lower():\n        raise RuntimeError(\'Non-memory failure; stop for diagnosis\')\n    return result\n\n\ndef screen(config):\n    if any(r[\'config\'] == config for r in results):\n        return\n    if len([r for r in results if r[\'label\'].startswith(\'screen\')]) >= 12:\n        return\n    return trial(config, \'screen-\' + str(len(results)).zfill(2))\n\n\ndef fastest():\n    valid = [r for r in results if r[\'eligible\']]\n    if not valid:\n        raise RuntimeError(\'No eligible candidate; inspect errors before consuming more credits\')\n    return max(valid, key=lambda r:r[\'trajectories_per_second\'])[\'config\'].copy()\n\n\ntry:\n    gpu = subprocess.check_output([\'nvidia-smi\', \'--query-gpu=name,memory.total,driver_version\', \'--format=csv,noheader\'], text=True).strip()\n    assert \'RTX PRO 6000\' in gpu and \'Blackwell\' in gpu, gpu\n    (OUT / \'hardware.json\').write_text(json.dumps(dict(gpu=gpu, cpu_count=os.cpu_count(), affinity=len(os.sched_getaffinity(0)), python=sys.version)))\n    if not REPO.exists():\n        run([\'git\', \'clone\', \'--depth\', \'1\', PROTOCOL[\'repository\'], str(REPO)])\n    assert subprocess.check_output([\'git\', \'rev-parse\', \'HEAD\'], cwd=REPO, text=True).strip() == PROTOCOL[\'commit\']\n    assert not subprocess.check_output([\'git\',\'status\',\'--porcelain\',\'--untracked-files=no\'],cwd=REPO,text=True).strip()\n    run([sys.executable, \'-m\', \'pip\', \'install\', \'-q\', \'cmake\', \'ninja\', \'pybind11\', \'tyro\', \'numpy>=2\', \'wheel\', \'setuptools\'])\n    run([sys.executable, \'-m\', \'pip\', \'install\', \'-q\', \'--no-build-isolation\', \'--no-deps\', \'-e\', str(REPO / \'nanopokerlib\')])\n    run([sys.executable, \'-m\', \'pip\', \'install\', \'-q\', \'--no-deps\', \'-e\', str(REPO)])\n    (OUT / \'packages.txt\').write_text(subprocess.check_output([sys.executable, \'-m\', \'pip\', \'freeze\'], text=True))\n    (OUT / \'protocol.json\').write_text(json.dumps(PROTOCOL, indent=2))\n    print(\'SETUP_SECONDS \' + str(time.monotonic()-START), flush=True)\n    for config in PROTOCOL[\'candidates\']:\n        result = screen(config)\n        if result and result[\'exit_code\'] != 0 and \'out of memory\' not in result.get(\'error_tail\', \'\').lower():\n            raise RuntimeError(\'Non-memory failure; stop search for diagnosis\')\n    anchor = fastest()\n    for threads in (2, 4, 8):\n        screen(dict(anchor, threads=threads))\n    anchor = fastest()\n    for mini in sorted({2, 4, 8} - {anchor[\'mini_batches\']}):\n        screen(dict(anchor, mini_batches=mini))\n    anchor = fastest()\n    for rollout in sorted({max(128, anchor[\'rollout\']//2), anchor[\'rollout\']*2}):\n        screen(dict(anchor, rollout=rollout))\n    anchor = fastest()\n    for collect in (anchor[\'collect\']//2, anchor[\'collect\']*2):\n        if 64 <= collect <= 2048:\n            screen(dict(anchor, collect=collect))\n    finalists = sorted((r for r in results if r[\'eligible\']), key=lambda r:r[\'trajectories_per_second\'], reverse=True)[:2]\n    verify = []\n    for seed in (0, 1):\n        for index in ([0, 1] if seed == 0 else [1, 0]):\n            if index < len(finalists):\n                verify.append(trial(finalists[index][\'config\'], f\'verify-{index}-seed{seed}\', 16, 16, seed))\n    summary = []\n    for finalist in finalists:\n        runs = [r for r in verify if r[\'config\'] == finalist[\'config\']]\n        if len(runs) == 2 and all(r[\'eligible\'] for r in runs):\n            seconds = sum(r[\'seconds\'] for r in runs)\n            summary.append(dict(config=finalist[\'config\'], trajectories_per_second=sum(sum(b[\'trajectories\'] for b in r[\'blocks\']) for r in runs)/seconds,\n                headroom_mib=min(r[\'headroom_mib\'] for r in runs), gpu_peak_mib=max(r[\'gpu_peak_mib\'] for r in runs),\n                trials=[r[\'label\'] for r in runs]))\n    assert summary, \'No finalist passed verification\'\n    best = max(summary, key=lambda r:r[\'trajectories_per_second\'])\n    (OUT / \'summary.json\').write_text(json.dumps(dict(best=best, finalists=summary, total_seconds=time.monotonic()-START), indent=2))\n    print(\'BEST \' + json.dumps(best), flush=True)\nexcept BaseException:\n    (OUT / \'failure.txt\').write_text(traceback.format_exc())\n    traceback.print_exc()\nfinally:\n    import shutil\n    shutil.make_archive(str(ROOT / \'results\'), \'zip\', OUT)\n    (ROOT / \'done.json\').write_text(json.dumps(dict(seconds=time.monotonic()-START, success=(OUT / \'summary.json\').exists())))\n', 'protocol.json': '{\n  "repository": "https://github.com/AtaraxosAI/doudizhu.git",\n  "commit": "acdcf199cf422e2b683cb22142b8e7cb33b14460",\n  "algorithm": "original VRPOTrainer + CentralCritic(qvalue)",\n  "fixed": {\n    "model": "v1.3",\n    "precision": "FP32/TF32",\n    "compile": "default Inductor",\n    "policy_epochs": 4,\n    "critic_epochs": 4,\n    "replay_buffer_scale": 16,\n    "optimizer": "Muon/AdamW"\n  },\n  "primary_metric": "delivered training trajectories per steady-state second",\n  "memory_gate": "max(NVML sampled peak, PyTorch peak reserved + 512 MiB) <= total VRAM - max(3072 MiB, 15% total VRAM)",\n  "screen": {\n    "warmup": 16,\n    "measure": 8\n  },\n  "verification": {\n    "warmup": 16,\n    "measure": 16,\n    "block_size": 8,\n    "seeds": [\n      0,\n      1\n    ]\n  },\n  "candidates": [\n    {\n      "rollout": 512,\n      "collect": 256,\n      "mini_batches": 4,\n      "threads": 4\n    },\n    {\n      "rollout": 1024,\n      "collect": 512,\n      "mini_batches": 4,\n      "threads": 6\n    },\n    {\n      "rollout": 1024,\n      "collect": 1024,\n      "mini_batches": 4,\n      "threads": 6\n    },\n    {\n      "rollout": 1024,\n      "collect": 1024,\n      "mini_batches": 8,\n      "threads": 6\n    },\n    {\n      "rollout": 2048,\n      "collect": 1024,\n      "mini_batches": 4,\n      "threads": 6\n    },\n    {\n      "rollout": 1024,\n      "collect": 512,\n      "mini_batches": 2,\n      "threads": 6\n    }\n  ],\n  "adaptive": "Up to 12 screens; compare 2/4/8 threads and minibatches 2/4/8 around winner; verify top two with seeds 0/1. 55 minute job budget.",\n  "caveats": "Replay scale 16 is a memory-conscious tuning choice versus repository default 64. Batch and minibatch changes affect learning dynamics. Optimize measured throughput, not strength or convergence. No global optimum claim.",\n  "checkpoints_during_tuning": false,\n  "preanalysis": "Original GPU replay holds 487112 bytes/trajectory. Replay scale16 with collect256/512/1024 consumes1.86/3.72/7.43GiB. Full collect critic bootstrap cannot be reduced by minibatches. G4 historical hardware RTX PRO6000 Blackwell 94.97GiB; verify hardware on allocation. Keep >=15% VRAM or3GiB. Preserve all model dimensions, precision, epochs, optimizer and learning rate defaults; use clean upstream commit, never modified local trainer."\n}'}
